import React, { useEffect, useRef, useState } from "react";
import Hls from "hls.js";

const VideoPlayer = ({
  src,
  autoPlay = false,
  style = {},
  showQualitySelector = true,
}) => {
  const videoRef = useRef(null);
  const hlsRef = useRef(null);

  const [qualityLevels, setQualityLevels] = useState([]);
  const [selectedQuality, setSelectedQuality] = useState(-1);
  const [canSelectQuality, setCanSelectQuality] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !src) return;

    const isHlsSource = src.toLowerCase().indexOf(".m3u8") !== -1;
    const isMp4Source = src.toLowerCase().indexOf(".mp4") !== -1;

    setQualityLevels([]);
    setSelectedQuality(-1);
    setCanSelectQuality(false);

    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    video.pause();
    video.removeAttribute("src");
    video.load();

    if (isHlsSource) {
      if (Hls.isSupported()) {
        const hls = new Hls({
          enableWorker: true,
          lowLatencyMode: true,
        });

        hlsRef.current = hls;
        hls.loadSource(src);
        hls.attachMedia(video);

        hls.on(Hls.Events.MANIFEST_PARSED, function(event, data) {
          const levels = data && data.levels ? data.levels : hls.levels;

          setQualityLevels(levels || []);
          setCanSelectQuality(levels && levels.length > 1 ? true : false);

          if (autoPlay) {
            video.play().catch(function() {});
          }
        });
      } else if (video.canPlayType("application/vnd.apple.mpegurl")) {
        video.src = src;

        if (autoPlay) {
          video.play().catch(function() {});
        }
      }
    } else if (isMp4Source) {
      video.src = src;
      video.load();

      if (autoPlay) {
        video.play().catch(function() {});
      }
    } else {
      video.src = src;
      video.load();

      if (autoPlay) {
        video.play().catch(function() {});
      }
    }

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
        hlsRef.current = null;
      }
    };
  }, [src, autoPlay]);

  const handleQualityChange = function(event) {
    const value = parseInt(event.target.value, 10);
    setSelectedQuality(value);

    if (hlsRef.current) {
      hlsRef.current.loadLevel = value;
    }
  };

  const getQualityLabel = function(level, index) {
    if (level && level.height) {
      return level.height + "p";
    }

    if (level && level.bitrate) {
      return Math.round(level.bitrate / 1000) + " kbps";
    }

    return "Nivel " + (index + 1);
  };

  const showSelector =
    showQualitySelector &&
    canSelectQuality &&
    src &&
    src.toLowerCase().indexOf(".m3u8") !== -1;

  return (
    <div>
      {showSelector ? (
        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            alignItems: "center",
            marginBottom: 8,
            gap: 8,
          }}
        >
          <label htmlFor="quality-select" style={{ color: "#666" }}>
            Calidad
          </label>

          <select
            id="quality-select"
            value={selectedQuality}
            onChange={handleQualityChange}
            style={{
              padding: "6px 10px",
              borderRadius: 6,
              border: "1px solid #d9d9d9",
              background: "#fff",
              cursor: "pointer",
            }}
          >
            <option value={-1}>Auto</option>
            {qualityLevels.map(function(level, index) {
              return (
                <option key={index} value={index}>
                  {getQualityLabel(level, index)}
                </option>
              );
            })}
          </select>
        </div>
      ) : null}

      <video
        ref={videoRef}
        controls
        style={{ width: "100%", borderRadius: 8, background: "#000", ...style }}
      />
    </div>
  );
};

export default VideoPlayer;
