import React, { Component } from "react";
import {
  Card,
  Col,
  Row,
  Tag,
  Empty,
  Spin,
  Alert,
  Modal,
  Input,
  Select,
  Button,
  Icon,
  Radio,
} from "antd";
import VideoPlayer from "./VideoPlayer";

import API_BASE_URL from "./config";

const { Search } = Input;
const { Option } = Select;

const VOD_API = `${API_BASE_URL}/public-api/videos/ready`;

class VOD extends Component {
  state = {
    videos: [],
    loading: true,
    error: null,
    selected: null,
    searchText: "",
    sortOrder: "newest",
    playbackType: "hls",
  };

  componentDidMount() {
    this.fetchVideos();
  }

  fetchVideos = async () => {
    try {
      const res = await fetch(VOD_API);

      if (!res.ok) throw new Error(`HTTP ${res.status}`);

      const videos = await res.json();

      this.setState({
        videos,
        loading: false,
        error: null,
      });
    } catch (err) {
      this.setState({
        loading: false,
        error: err.message,
      });
    }
  };

  openVideo = (video) => {
    var playbackType = "hls";

    if (!video.hls_path && video.mp4_path) {
      playbackType = "mp4";
    }

    this.setState({
      selected: video,
      playbackType: playbackType,
    });
  };

  closeVideo = () => {
    this.setState({
      selected: null,
      playbackType: "hls",
    });
  };

  handleSearchChange = (event) => {
    this.setState({ searchText: event.target.value });
  };

  handleSortChange = (value) => {
    this.setState({ sortOrder: value });
  };

  handlePlaybackTypeChange = (e) => {
    this.setState({ playbackType: e.target.value });
  };

  getFilteredVideos = () => {
    const { videos, searchText, sortOrder } = this.state;
    const normalizedSearch = searchText.trim().toLowerCase();

    let filteredVideos = videos.filter((video) => {
      const title = video.title ? video.title.toLowerCase() : "";
      const streamKey = video.stream_key ? video.stream_key.toLowerCase() : "";

      if (!normalizedSearch) return true;

      return (
        title.indexOf(normalizedSearch) !== -1 ||
        streamKey.indexOf(normalizedSearch) !== -1
      );
    });

    filteredVideos.sort((a, b) => {
      const dateA = new Date(a.created_at).getTime();
      const dateB = new Date(b.created_at).getTime();

      if (sortOrder === "oldest") {
        return dateA - dateB;
      }

      if (sortOrder === "az") {
        const titleA = a.title ? a.title.toLowerCase() : "";
        const titleB = b.title ? b.title.toLowerCase() : "";
        return titleA.localeCompare(titleB);
      }

      if (sortOrder === "za") {
        const titleA = a.title ? a.title.toLowerCase() : "";
        const titleB = b.title ? b.title.toLowerCase() : "";
        return titleB.localeCompare(titleA);
      }

      return dateB - dateA;
    });

    return filteredVideos;
  };

  getPlaybackSrc = () => {
    const { selected, playbackType } = this.state;

    if (!selected) return null;

    if (playbackType === "mp4") {
      return selected.mp4_path || null;
    }

    return selected.hls_path || null;
  };

  renderFormatTags = (video) => {
    const hasHls = !!video.hls_path;
    const hasMp4 = !!video.mp4_path;

    return (
      <div style={{ marginBottom: 16 }}>
        <div
          style={{
            fontSize: 12,
            color: "#8c8c8c",
            marginBottom: 8,
            textTransform: "uppercase",
            letterSpacing: 0.4,
            fontWeight: 700,
          }}
        >
          Formatos disponibles
        </div>

        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {hasHls ? (
            <Tag
              color="geekblue"
              style={{
                borderRadius: 999,
                padding: "3px 10px",
                fontWeight: 600,
                marginRight: 0,
              }}
            >
              HLS
            </Tag>
          ) : null}

          {hasMp4 ? (
            <Tag
              color="purple"
              style={{
                borderRadius: 999,
                padding: "3px 10px",
                fontWeight: 600,
                marginRight: 0,
              }}
            >
              MP4
            </Tag>
          ) : null}

          {!hasHls && !hasMp4 ? (
            <Tag
              style={{
                borderRadius: 999,
                padding: "3px 10px",
                fontWeight: 600,
                marginRight: 0,
              }}
            >
              Sin formato
            </Tag>
          ) : null}
        </div>
      </div>
    );
  };

  renderVideoCard = (video) => {
    const hasMp4 = !!video.mp4_path;

    return (
      <Card
        hoverable
        onClick={() => this.openVideo(video)}
        bodyStyle={{ padding: 0 }}
        style={{
          borderRadius: 18,
          overflow: "hidden",
          border: "1px solid #e8e8e8",
          boxShadow: "0 8px 24px rgba(0,0,0,0.05)",
          transition: "all 0.2s ease",
          cursor: "pointer",
          background: "#fff",
          height: "100%",
        }}
      >
        <div
          style={{
            height: 150,
            background: "linear-gradient(135deg, #1f1f1f 0%, #434343 100%)",
            position: "relative",
            display: "flex",
            alignItems: "flex-end",
            padding: 18,
          }}
        >
          <div
            style={{
              position: "absolute",
              top: 14,
              right: 14,
              display: "flex",
              gap: 8,
              flexWrap: "wrap",
              justifyContent: "flex-end",
            }}
          >
            <Tag
              color="green"
              style={{
                borderRadius: 999,
                padding: "2px 10px",
                fontWeight: 600,
                marginRight: 0,
              }}
            >
              READY
            </Tag>

            {hasMp4 ? (
              <Tag
                color="blue"
                style={{
                  borderRadius: 999,
                  padding: "2px 10px",
                  fontWeight: 600,
                  marginRight: 0,
                }}
              >
                MP4 disponible
              </Tag>
            ) : null}
          </div>

          <div
            style={{
              width: 58,
              height: 58,
              borderRadius: "50%",
              background: "rgba(255,255,255,0.16)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Icon type="play-circle" style={{ fontSize: 30, color: "#fff" }} />
          </div>
        </div>

        <div style={{ padding: 20 }}>
          <div
            style={{
              fontSize: 20,
              fontWeight: 700,
              color: "#1f1f1f",
              marginBottom: 12,
              lineHeight: 1.25,
            }}
          >
            {video.title}
          </div>

          <div style={{ marginBottom: 8, color: "#595959" }}>
            <Icon type="video-camera" style={{ marginRight: 8 }} />
            <strong>Stream key:</strong> {video.stream_key}
          </div>

          <div style={{ marginBottom: 16, color: "#595959" }}>
            <Icon type="calendar" style={{ marginRight: 8 }} />
            <strong>Grabado:</strong>{" "}
            {new Date(video.created_at).toLocaleString("es-ES")}
          </div>

          {this.renderFormatTags(video)}

          <Button
            type="primary"
            icon="play-circle"
            style={{
              width: "100%",
              height: 42,
              borderRadius: 10,
              fontWeight: 600,
            }}
          >
            Reproducir vídeo
          </Button>
        </div>
      </Card>
    );
  };

  render() {
    const {
      loading,
      error,
      selected,
      searchText,
      sortOrder,
      playbackType,
    } = this.state;

    const filteredVideos = this.getFilteredVideos();
    const currentPlaybackSrc = this.getPlaybackSrc();

    const hasHls = selected && selected.hls_path;
    const hasMp4 = selected && selected.mp4_path;

    if (loading) {
      return <Spin size="large" style={{ display: "block", marginTop: 80 }} />;
    }

    if (error) {
      return (
        <Alert
          type="error"
          message={`Error al cargar videos: ${error}`}
          style={{ margin: 24 }}
        />
      );
    }

    return (
      <div
        style={{
          padding: "20px 20px 36px",
          maxWidth: 1480,
          margin: "0 auto",
        }}
      >
        <div style={{ marginBottom: 28 }}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: 12,
              marginBottom: 10,
            }}
          >
            <h2
              style={{
                margin: 0,
                fontSize: 32,
                fontWeight: 700,
                color: "#1f1f1f",
              }}
            >
              Biblioteca VOD
            </h2>

            <Tag
              color="blue"
              style={{
                borderRadius: 999,
                padding: "6px 14px",
                fontSize: 14,
                marginRight: 0,
              }}
            >
              {filteredVideos.length} vídeo(s)
            </Tag>
          </div>

          <div style={{ color: "#8c8c8c", fontSize: 15 }}>
            Explora, filtra y reproduce grabaciones disponibles
          </div>
        </div>

        <Card
          bodyStyle={{ padding: 18 }}
          style={{
            marginBottom: 32,
            borderRadius: 16,
            border: "1px solid #ececec",
            boxShadow: "0 4px 18px rgba(0,0,0,0.03)",
          }}
        >
          <Row gutter={[16, 16]}>
            <Col xs={24} md={16}>
              <Search
                placeholder="Buscar por título o stream key"
                value={searchText}
                onChange={this.handleSearchChange}
                allowClear
                size="large"
              />
            </Col>

            <Col xs={24} md={8}>
              <Select
                value={sortOrder}
                onChange={this.handleSortChange}
                size="large"
                style={{ width: "100%" }}
              >
                <Option value="newest">Más recientes primero</Option>
                <Option value="oldest">Más antiguos primero</Option>
                <Option value="az">Título A-Z</Option>
                <Option value="za">Título Z-A</Option>
              </Select>
            </Col>
          </Row>
        </Card>

        {filteredVideos.length === 0 ? (
          <Card
            bodyStyle={{ padding: 40 }}
            style={{
              borderRadius: 16,
              border: "1px solid #ececec",
            }}
          >
            <Empty description="No hay grabaciones disponibles con esos filtros" />
          </Card>
        ) : (
          <Row gutter={[0, 26]}>
            {filteredVideos.map((video) => (
              <Col
                key={video.id}
                xs={24}
                md={12}
                xl={8}
                style={{ paddingLeft: 12, paddingRight: 12 }}
              >
                {this.renderVideoCard(video)}
              </Col>
            ))}
          </Row>
        )}

        <Modal
          title={selected ? selected.title : null}
          visible={!!selected}
          onCancel={this.closeVideo}
          footer={null}
          width={980}
          destroyOnClose
        >
          {selected ? (
            <div>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  flexWrap: "wrap",
                  gap: 16,
                  marginBottom: 18,
                }}
              >
                <div style={{ color: "#595959" }}>
                  <div style={{ marginBottom: 6 }}>
                    <Icon type="video-camera" style={{ marginRight: 8 }} />
                    <strong>Stream key:</strong> {selected.stream_key}
                  </div>
                  <div>
                    <Icon type="calendar" style={{ marginRight: 8 }} />
                    <strong>Fecha:</strong>{" "}
                    {new Date(selected.created_at).toLocaleString("es-ES")}
                  </div>
                </div>

                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 12,
                    flexWrap: "wrap",
                  }}
                >
                  <Radio.Group
                    value={playbackType}
                    onChange={this.handlePlaybackTypeChange}
                    buttonStyle="solid"
                  >
                    <Radio.Button value="hls" disabled={!hasHls}>
                      HLS
                    </Radio.Button>
                    <Radio.Button value="mp4" disabled={!hasMp4}>
                      MP4
                    </Radio.Button>
                  </Radio.Group>

                  {hasMp4 ? (
                    <Button
                      icon="download"
                      href={selected.mp4_path}
                      target="_blank"
                    >
                      Descargar MP4
                    </Button>
                  ) : null}
                </div>
              </div>

              {currentPlaybackSrc ? (
                <VideoPlayer
                  key={currentPlaybackSrc}
                  src={currentPlaybackSrc}
                  autoPlay
                  showQualitySelector={playbackType === "hls"}
                />
              ) : (
                <Alert
                  type="warning"
                  message="No hay una fuente de reproducción disponible para este vídeo"
                />
              )}
            </div>
          ) : null}
        </Modal>
      </div>
    );
  }
}

export default VOD;
